const upsertReview = `-- name: UpsertReview :one
INSERT INTO reviews (user_id, story_id, rating, content)
VALUES ($1, $2, $3, $4)
ON CONFLICT (user_id, story_id)
DO UPDATE SET
    rating = EXCLUDED.rating,
    content = EXCLUDED.content
RETURNING id, user_id, story_id, rating, content, created_at
`

type UpsertReviewParams struct {
	UserID  uuid.NullUUID `json:"user_id"`
	StoryID uuid.NullUUID `json:"story_id"`
	Rating  *int16        `json:"rating"`
	Content *string       `json:"content"`
}

func (q *Queries) UpsertReview(ctx context.Context, arg UpsertReviewParams) (Review, error) {
	row := q.db.QueryRow(ctx, upsertReview,
		arg.UserID,
		arg.StoryID,
		arg.Rating,
		arg.Content,
	)
	var i Review
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.StoryID,
		&i.Rating,
		&i.Content,
		&i.CreatedAt,
	)
	return i, err
}
